(function(){const n=document.getElementById("site-header"),e=document.getElementById("nav-toggle"),t=document.getElementById("site-nav"),s=()=>{if(!n)return;n.classList.toggle("is-scrolled",window.scrollY>12)};window.addEventListener("scroll",s,{passive:!0}),s(),e&&t&&(e.addEventListener("click",()=>{const n=t.classList.toggle("is-open");e.setAttribute("aria-expanded",String(n))}),t.querySelectorAll("a").forEach(n=>{n.addEventListener("click",()=>{t.classList.remove("is-open"),e.setAttribute("aria-expanded","false")})}));const o=document.querySelectorAll(".reveal");if("IntersectionObserver"in window){const e=new IntersectionObserver(t=>{t.forEach(t=>{t.isIntersecting&&(t.target.classList.add("is-visible"),e.unobserve(t.target))})},{threshold:.14,rootMargin:"0px 0px -40px 0px"});o.forEach(t=>e.observe(t))}else o.forEach(e=>e.classList.add("is-visible"))})()